    running = false;
    paused = false;
    saveBest();
    updateHud();
    message = text;
    showResult(text);
  }

  function reset() {
    score = 0;
    lives = 5;
    docked = 0;
    boats = [];
    spawnTimer = 0;
    running = false;
    paused = false;
    runEnded = false;
    message = "Tap Start Harbor";
    switches.forEach(s => s.dir = 0);
    setNextTarget();
    hidePanels();
    updateHud();
    draw();
  }

  function updateHud() {
    scoreEl.textContent = score;
    bestEl.textContent = best;
    livesEl.textContent = lives;
    dockedEl.textContent = docked;
  }

  function beginGame() {
    if (runEnded || lives <= 0 || docked >= 12) reset();
    hidePanels();
    running = true;
    paused = false;
    runEnded = false;
    message = "Match boats to piers!";
    showStartHelpUntil = performance.now() + 15000;
    if (boats.length === 0) spawnBoat();
  }

  function spawnBoat() {
    const target = nextTarget;
    const startLane = Math.floor(Math.random() * 3);
    boats.push({
      x: -70,
      lane: startLane,
      y: lanes[startLane],
      target,
      speed: 72 + docked * 2.5,
      used: new Set()
    });
    setNextTarget();
  }

  function cycleSwitch(index) {
    const s = switches[index];
    if (!s || runEnded) return;
    s.dir += 1;
    if (s.dir > 1) s.dir = -1;
    message = `Switch ${index + 1} changed!`;
    draw();
  }

  function switchSymbol(dir) {
    if (dir === -1) return "↑";
    if (dir === 1) return "↓";
    return "→";
  }

  function drawWater() {
    ctx.fillStyle = "#55c8ee";
    ctx.fillRect(0, 0, W, H);

    for (let i = 0; i < lanes.length; i++) {
      ctx.strokeStyle = "rgba(255,255,255,.7)";
      ctx.lineWidth = 24;
      ctx.beginPath();
      ctx.moveTo(0, lanes[i]);
      ctx.lineTo(W, lanes[i]);
      ctx.stroke();

      ctx.strokeStyle = "rgba(23,111,144,.35)";
      ctx.lineWidth = 2;
      ctx.setLineDash([10, 12]);
      ctx.beginPath();
      ctx.moveTo(0, lanes[i]);
      ctx.lineTo(W, lanes[i]);
      ctx.stroke();
      ctx.setLineDash([]);
    }

    ctx.fillStyle = "#c98b45";
    ctx.fillRect(W - 88, 60, 70, 310);

    colors.forEach((c, i) => {
      const y = lanes[i];
      ctx.fillStyle = c.fill;
      ctx.fillRect(W - 76, y - 30, 52, 60);
      ctx.fillStyle = "#123";
      ctx.font = "bold 16px system-ui";
      ctx.textAlign = "center";
      ctx.fillText(c.name, W - 50, y + 5);
    });
  }

  function drawSwitches() {
    switches.forEach((s, i) => {
      const y = lanes[s.lane];

      ctx.fillStyle = "rgba(255,255,255,.86)";
      ctx.strokeStyle = "#176f90";
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.roundRect(s.x - 22, y - 56, 44, 20, 9);
      ctx.fill();
      ctx.stroke();

      ctx.fillStyle = "#123";
      ctx.font = "bold 13px system-ui";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText("Switch " + (i + 1), s.x, y - 46);

      ctx.fillStyle = "#ffffff";
      ctx.strokeStyle = "#126b8f";
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.roundRect(s.x - 28, y - 28, 56, 56, 12);
      ctx.fill();
      ctx.stroke();

      ctx.fillStyle = "#126b8f";
      ctx.font = "bold 30px system-ui";
      ctx.fillText(switchSymbol(s.dir), s.x, y - 2);

      ctx.fillStyle = "#123";
      ctx.font = "bold 12px system-ui";
      ctx.fillText(String(i + 1), s.x, y + 24);
    });
  }

  function drawBoat(b) {
    const y = b.y;

    ctx.fillStyle = "#5a341f";
    ctx.beginPath();
    ctx.moveTo(b.x - 34, y + 13);
    ctx.lineTo(b.x + 30, y + 13);
    ctx.lineTo(b.x + 42, y - 2);
    ctx.lineTo(b.x - 42, y - 2);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = colors[b.target].fill;
    ctx.beginPath();
    ctx.roundRect(b.x - 22, y - 30, 42, 28, 8);
    ctx.fill();

    ctx.fillStyle = "white";
    ctx.beginPath();
    ctx.arc(b.x - 8, y - 16, 4, 0, Math.PI * 2);
    ctx.arc(b.x + 8, y - 16, 4, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = "#123";
    ctx.font = "bold 13px system-ui";
    ctx.textAlign = "center";
    ctx.fillText(colors[b.target].name, b.x, y + 32);
  }

  function drawNextPreview() {
    ctx.fillStyle = "rgba(255,255,255,.92)";
    ctx.strokeStyle = "#176f90";
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.roundRect(14, 15, 150, 48, 14);
    ctx.fill();
    ctx.stroke();

    ctx.fillStyle = "#123";
    ctx.font = "bold 13px system-ui";
    ctx.textAlign = "left";
    ctx.textBaseline = "middle";
    ctx.fillText("Next tug:", 26, 39);

    ctx.fillStyle = colors[nextTarget].fill;
    ctx.beginPath();
    ctx.roundRect(94, 25, 50, 28, 8);
    ctx.fill();

    ctx.fillStyle = "#123";
    ctx.font = "bold 11px system-ui";
    ctx.textAlign = "center";
    ctx.fillText(colors[nextTarget].name, 119, 40);
  }

  function drawStartHelp() {
    if (performance.now() > showStartHelpUntil || !running) return;

    ctx.fillStyle = "rgba(255,249,215,.94)";
    ctx.strokeStyle = "#e9ca62";
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.roundRect(188, 368, 304, 42, 14);
    ctx.fill();
    ctx.stroke();

    ctx.fillStyle = "#123";
    ctx.font = "bold 14px system-ui";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText("First 15 sec: use 1–6 or tap labeled switches", W / 2, 389);
  }

  function drawMessage() {
    if (!message) return;
    ctx.fillStyle = "rgba(255,255,255,.9)";
    ctx.strokeStyle = "#176f90";
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.roundRect(190, 15, 365, 46, 14);
    ctx.fill();
    ctx.stroke();

    ctx.fillStyle = "#123";
    ctx.font = "bold 20px system-ui";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(message, 372, 39);
  }

  function draw() {
    drawWater();
    drawSwitches();
    boats.forEach(drawBoat);
    drawNextPreview();
    drawMessage();
    drawStartHelp();
  }

  function update(dt) {
    if (!running || paused) return;

    spawnTimer -= dt;
    if (spawnTimer <= 0) {
      spawnBoat();
      spawnTimer = Math.max(1.15, 2.15 - docked * 0.04);
    }

    boats.forEach(b => {
      b.x += b.speed * dt;

      switches.forEach((s, index) => {
        if (b.used.has(index)) return;
        if (Math.abs(b.x - s.x) < 4 && b.lane === s.lane) {
          b.used.add(index);
          b.lane = Math.max(0, Math.min(2, b.lane + s.dir));
        }
      });

      const targetY = lanes[b.lane];
      b.y += (targetY - b.y) * Math.min(1, dt * 8);
    });

    boats = boats.filter(b => {
      if (b.x < W - 95) return true;

      if (b.lane === b.target) {
        score += 10;
        docked += 1;
        message = "Nice docking!";
      } else {
        lives -= 1;
        message = "Wrong pier!";
      }

      updateHud();

      if (docked >= 12) endRun("Harbor complete!");
      if (lives <= 0) endRun("Harbor closed!");

      return false;
    });
  }

  function loop(t) {
    const dt = Math.min(0.033, (t - lastTime) / 1000 || 0);
    lastTime = t;
    update(dt);
    draw();
    requestAnimationFrame(loop);
  }

  function pointerToCanvas(e) {
    const rect = canvas.getBoundingClientRect();
    return {
      x: (e.clientX - rect.left) * (canvas.width / rect.width),
      y: (e.clientY - rect.top) * (canvas.height / rect.height)
    };
  }

  canvas.addEventListener("pointerdown", e => {
    e.preventDefault();
    const p = pointerToCanvas(e);

    for (let i = 0; i < switches.length; i++) {
      const s = switches[i];
      const y = lanes[s.lane];
      if (p.x >= s.x - 40 && p.x <= s.x + 40 && p.y >= y - 64 && p.y <= y + 38) {
        cycleSwitch(i);
        return;
      }
    }
  });

  window.addEventListener("keydown", e => {
    const n = Number(e.key);

    if (n >= 1 && n <= 6) {
      e.preventDefault();
      cycleSwitch(n - 1);
    }

    if (e.key === " " || e.key.toLowerCase() === "p") {
      e.preventDefault();
      if (!running) return;
      paused = !paused;
      message = paused ? "Paused" : "Match boats to piers!";
    }

    if (e.key === "Enter" && runEnded) {
      e.preventDefault();
      reset();
      beginGame();
    }
  });

  document.getElementById("startBtn").addEventListener("click", () => {
    if (!running && boats.length === 0 && docked === 0 && score === 0) {
      startPanel.style.display = "flex";
    } else {
      beginGame();
    }
  });

  document.getElementById("beginBtn").addEventListener("click", beginGame);

  document.getElementById("pauseBtn").addEventListener("click", () => {
    if (!running) return;
    paused = !paused;
    message = paused ? "Paused" : "Match boats to piers!";
  });

  document.getElementById("resetBtn").addEventListener("click", () => {
    saveBest();
    reset();
  });

  document.getElementById("playAgainBtn").addEventListener("click", () => {
    reset();
    beginGame();
  });

  if (!CanvasRenderingContext2D.prototype.roundRect) {
    CanvasRenderingContext2D.prototype.roundRect = function(x, y, w, h, r) {
      this.beginPath();
      this.moveTo(x + r, y);
      this.arcTo(x + w, y, x + w, y + h, r);
      this.arcTo(x + w, y + h, x, y + h, r);
      this.arcTo(x, y + h, x, y, r);
      this.arcTo(x, y, x + w, y, r);
      this.closePath();
      return this;
    };
  }

  reset();
  requestAnimationFrame(loop);
})();
