    ctx.fillStyle = "#5a341f";
    ctx.beginPath();
    ctx.moveTo(b.x - 34, y + 13);
    ctx.lineTo(b.x + 30, y + 13);
    ctx.lineTo(b.x + 42, y - 2);
    ctx.lineTo(b.x - 42, y - 2);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = colors[b.target].fill;
    roundRect(ctx, b.x - 22, y - 30, 42, 28, 8);
    ctx.fill();

    ctx.fillStyle = "white";
    ctx.beginPath();
    ctx.arc(b.x - 8, y - 16, 4, 0, Math.PI * 2);
    ctx.arc(b.x + 8, y - 16, 4, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = "#123";
    ctx.font = "bold 13px system-ui";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(colors[b.target].name, b.x, y + 32);
  }

  function drawNextPreview() {
    ctx.fillStyle = "rgba(255,255,255,.92)";
    ctx.strokeStyle = "#176f90";
    ctx.lineWidth = 3;
    roundRect(ctx, 14, 15, 150, 48, 14);
    ctx.fill();
    ctx.stroke();

    ctx.fillStyle = "#123";
    ctx.font = "bold 13px system-ui";
    ctx.textAlign = "left";
    ctx.textBaseline = "middle";
    ctx.fillText("Next tug:", 26, 39);

    ctx.fillStyle = colors[nextTarget].fill;
    roundRect(ctx, 94, 25, 50, 28, 8);
    ctx.fill();

    ctx.fillStyle = "#123";
    ctx.font = "bold 11px system-ui";
    ctx.textAlign = "center";
    ctx.fillText(colors[nextTarget].name, 119, 40);
  }

  function drawStartHelp() {
    if (performance.now() > showStartHelpUntil || !running) return;

    ctx.fillStyle = "rgba(255,249,215,.94)";
    ctx.strokeStyle = "#e9ca62";
    ctx.lineWidth = 3;
    roundRect(ctx, 166, 368, 348, 42, 14);
    ctx.fill();
    ctx.stroke();

    ctx.fillStyle = "#123";
    ctx.font = "bold 14px system-ui";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText("Use 1–6 or tap the labeled water switches", W / 2, 389);
  }

  function drawMessage() {
    if (!message) return;

    ctx.fillStyle = "rgba(255,255,255,.9)";
    ctx.strokeStyle = "#176f90";
    ctx.lineWidth = 3;
    roundRect(ctx, 190, 15, 365, 46, 14);
    ctx.fill();
    ctx.stroke();

    ctx.fillStyle = "#123";
    ctx.font = "bold 20px system-ui";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(message, 372, 39);
  }

  function draw() {
    drawWater();
    drawSwitches();
    boats.forEach(drawBoat);
    drawNextPreview();
    drawMessage();
    drawStartHelp();
  }

  function update(dt) {
    if (!running || paused) return;

    spawnTimer -= dt;
    if (spawnTimer <= 0) {
      spawnBoat();
      spawnTimer = Math.max(1.15, 2.15 - docked * 0.04);
    }

    boats.forEach(b => {
      b.x += b.speed * dt;

      switches.forEach((s, index) => {
        if (b.used.has(index)) return;
        if (Math.abs(b.x - s.x) < 4 && b.lane === s.lane) {
          b.used.add(index);
          b.lane = Math.max(0, Math.min(2, b.lane + s.dir));
        }
      });

      const targetY = lanes[b.lane];
      b.y += (targetY - b.y) * Math.min(1, dt * 8);
    });

    boats = boats.filter(b => {
      if (b.x < W - 95) return true;

      if (b.lane === b.target) {
        score += 10;
        docked += 1;
        message = "Nice docking!";
      } else {
        lives -= 1;
        message = "Wrong pier!";
      }

      updateHud();

      if (docked >= 12) endRun("Harbor complete!");
      if (lives <= 0) endRun("Harbor closed!");

      return false;
    });
  }

  function loop(t) {
    const dt = Math.min(0.033, (t - lastTime) / 1000 || 0);
    lastTime = t;
    update(dt);
    draw();
    requestAnimationFrame(loop);
  }

  function pointerToCanvas(e) {
    const rect = canvas.getBoundingClientRect();
    return {
      x: (e.clientX - rect.left) * (canvas.width / rect.width),
      y: (e.clientY - rect.top) * (canvas.height / rect.height)
    };
  }

  canvas.addEventListener("pointerdown", e => {
    e.preventDefault();
    const p = pointerToCanvas(e);

    for (let i = 0; i < switches.length; i++) {
      const s = switches[i];
      const y = lanes[s.lane];
      if (p.x >= s.x - 44 && p.x <= s.x + 44 && p.y >= y - 66 && p.y <= y + 40) {
        cycleSwitch(i);
        return;
      }
    }
  }, { passive: false });

  window.addEventListener("keydown", e => {
    const n = Number(e.key);

    if (n >= 1 && n <= 6) {
      e.preventDefault();
      cycleSwitch(n - 1);
      return;
    }

    if (e.key === " " || e.key.toLowerCase() === "p") {
      e.preventDefault();
      if (!running) return;
      paused = !paused;
      message = paused ? "Paused" : "Match boats to piers!";
      return;
    }

    if (e.key === "Enter" && runEnded) {
      e.preventDefault();
      reset();
      beginGame();
    }
  });

  document.getElementById("startBtn").addEventListener("click", () => {
    if (!running && boats.length === 0 && docked === 0 && score === 0) {
      startPanel.style.display = "flex";
    } else {
      beginGame();
    }
  });

  document.getElementById("beginBtn").addEventListener("click", beginGame);

  document.getElementById("pauseBtn").addEventListener("click", () => {
    if (!running) return;
    paused = !paused;
    message = paused ? "Paused" : "Match boats to piers!";
  });

  document.getElementById("resetBtn").addEventListener("click", () => {
    saveBest();
    reset();
  });

  document.getElementById("playAgainBtn").addEventListener("click", () => {
    reset();
    beginGame();
  });

  reset();
  requestAnimationFrame(loop);
})();
</script>
</body>
</html>
